init.source:
static const float METRES_PER_UNIT = 1;
static const float GRAVITY = 9.81;
static const float CAPILLARY = 7.28e-05;
static const float DOMAIN = 0.15;
static const float MARKER_SPACING = 0.002;
static const float KERNEL_SUPPORT = 0.00538461538462;
static const float CONTACT_OFFSET = 0.000769230769231;
static const float FLIP_BLEND = 0;
static const float FILM_DIFFUSIVITY = 0.0001;
static const float3 DOMAIN_EXTENT = float3(0.15,0.05,0.05);
static const float3 DOMAIN_ORIGIN = float3(0.0,0.0,0.0);
static const uint3 BIN_DIMS = uint3(60,20,20);
static const uint BIN_RES = 60u;
#include "fluid/config.slang"

float container(float3 p) { return max(-p.y, max(abs(p.x)-0.148, abs(p.z)-0.048)); }
float initial_field(float3 p) { return max(length(p-float3(0,0.030,0))-0.009,container(p)); }
bool initial_marker(uint id, out float3 p) {
 uint x=id%10; uint y=(id/10)%10; uint z=id/100;
 p=float3(x,y,z)*0.002-float3(0.009,0.009,0.009)+float3(0,0.030,0);
 return length(p-float3(0,0.030,0))<0.009;
}
float3 initial_velocity(float3 p,float dx) { return float3(0,-0.2,0); }
float initial_pressure(float3 p) { return 0; }
bool film_accept(float2 xz) { return abs(xz.x)<0.148 && abs(xz.y)<0.048; }
float film_height(float2 xz) { return 0; }
float3 boundary_velocity(float3 p,float time,float3 v) { return v; }

struct Inputs {int stage=0;};
#include "fluid/solver.slang"

